                      </div>
                    </div>
                  </div>
                </div>
              </div>

              {/* Wellness Tips Card */}
              <div className={`group relative overflow-hidden rounded-2xl border-2 transition-all duration-500 transform hover:scale-105 hover:-translate-y-2 shadow-xl backdrop-blur-md ${
