                  </svg>
                </div>
                <div className={`max-w-xs p-2 rounded-lg ${
                  isDarkMode ? 'bg-gray-700' : 'bg-gray-100'
                }`}>
                  <p className={`text-sm ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
                    Hello! 👋 How can I help you today?
                  </p>
                  <span className={`text-xs ${isDarkMode ? 'text-gray-400' : 'text-gray-500'}`}>
                    Just now
                  </span>
                </div>
              </div>

              {/* Quick Options */}
              <div className="space-y-2">
                <button className={`w-full p-2 rounded-lg text-left transition-all duration-300 hover:scale-105 ${
                  isDarkMode ? 'bg-gray-700 hover:bg-gray-600' : 'bg-gray-50 hover:bg-gray-100'
                }`}>
                  <div className="flex items-center">
                    <span className="text-lg mr-2">📦</span>
                    <span className={`text-sm ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
                      Track my order
                    </span>
                  </div>
                </button>

                <button className={`w-full p-2 rounded-lg text-left transition-all duration-300 hover:scale-105 ${
                  isDarkMode ? 'bg-gray-700 hover:bg-gray-600' : 'bg-gray-50 hover:bg-gray-100'
                }`}>
                  <div className="flex items-center">
                    <span className="text-lg mr-2">💳</span>
                    <span className={`text-sm ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
                      Payment issues
                    </span>
                  </div>
                </button>

                <button className={`w-full p-2 rounded-lg text-left transition-all duration-300 hover:scale-105 ${
                  isDarkMode ? 'bg-gray-700 hover:bg-gray-600' : 'bg-gray-50 hover:bg-gray-100'
                }`}>
                  <div className="flex items-center">
                    <span className="text-lg mr-2">🥛</span>
                    <span className={`text-sm ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
                      Product information
                    </span>
                  </div>
                </button>
              </div>
            </div>

            {/* Chat Input */}
            <div className="p-4 border-t border-purple-200/20 dark:border-purple-700/20">
              <div className="flex items-center space-x-2">
                <input 
                  type="text" 
                  placeholder="Type your message..." 
                  className={`flex-1 px-3 py-2 rounded-lg border text-sm ${
                    isDarkMode ? 'bg-gray-700 border-gray-600 text-white' : 'bg-white border-gray-300'
                  }`}
                />
                <button className="px-3 py-2 bg-gradient-to-r from-purple-500 to-pink-500 text-white font-semibold rounded-lg hover:from-purple-600 hover:to-pink-600 transition-all duration-300">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
                  </svg>
                </button>
              </div>
            </div>

          </div>
        </div>
      </>
    )}

    </>
  );
};

export default Home;
